pub async fn sysroot_lowered_put<H: SysrootHost>(root: &std::path::Path, cached: bool, key: Option<String>, rust: &str, host: &H) {
    let at = match key { Some(__nikaia_value) => __nikaia_value, None => return };
    if !cached { return; }
    let entry = nikaia_std::fs::path::join(&(root), std::path::Path::new(&(at)));
    match fs::create_dir(&entry, &fs::Root::Anywhere, true) {
        Ok(_) => {},
        Err(_error) => { return; },
    };
    let partial = host.unique_beside(&nikaia_std::fs::path::join(&(entry), std::path::Path::new(&(SYSROOT_LOWERED))));
    if sysroot_written(&partial, &nikaia_std::fs::path::join(&(entry), std::path::Path::new(&(SYSROOT_LOWERED))), rust).await {
        host.use_entry(&entry);
        return;
    }
    match fs::remove(&partial, &fs::Root::Anywhere, false) {
        Ok(_) => {},
        Err(_error) => { return; },
    };
}

pub(crate) async fn sysroot_written(partial: &std::path::Path, whole: &std::path::Path, rust: &str) -> bool {
    match fs::write(partial, &fs::Root::Anywhere, rust, false, true).await {
        Ok(_) => {},
        Err(_error) => { return false; },
    };
    match fs::rename(partial, whole, &fs::Root::Anywhere) {
        Ok(_) => {},
        Err(_error) => { return false; },
    };
    true
}

